<?php
require_once __DIR__.'/includes/bootstrap.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=filter_input(INPUT_POST,'listing_id',FILTER_VALIDATE_INT)?:0;if($action==='resolve_dispute'){$did=filter_input(INPUT_POST,'dispute_id',FILTER_VALIDATE_INT)?:0;$up=db()->prepare("UPDATE disputes SET status='resolved' WHERE id=? AND status<>'resolved'");$up->execute([$did]);set_flash('success','Dispute marked resolved.');redirect('admin.php');}if($action==='hide'){$st=db()->prepare("UPDATE listings SET status='hidden' WHERE id=? AND status<>'swapped'");$st->execute([$id]);set_flash('success','Listing moderated.');}elseif($action==='restore'){$st=db()->prepare("UPDATE listings SET status='available' WHERE id=? AND status='hidden'");$st->execute([$id]);set_flash('success','Listing restored.');}redirect('admin.php');}
$stats=['users'=>(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),'listings'=>(int)db()->query('SELECT COUNT(*) FROM listings')->fetchColumn(),'available'=>(int)db()->query("SELECT COUNT(*) FROM listings WHERE status='available'")->fetchColumn(),'requests'=>(int)db()->query('SELECT COUNT(*) FROM swap_requests')->fetchColumn(),'completed'=>(int)db()->query("SELECT COUNT(*) FROM swap_requests WHERE status='completed'")->fetchColumn()];
$users=db()->query('SELECT id,name,email,location,role,created_at FROM users ORDER BY created_at DESC LIMIT 200')->fetchAll();$listings=db()->query('SELECT l.*,u.name AS owner_name FROM listings l JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 200')->fetchAll();$disputes=db()->query("SELECT d.*,u.name AS reporter,sr.id AS swap_id FROM disputes d JOIN users u ON u.id=d.reported_by JOIN swap_requests sr ON sr.id=d.request_id ORDER BY d.created_at DESC LIMIT 100")->fetchAll();$pageTitle='Admin moderation — ReWear';require __DIR__.'/includes/header.php';?>
<section class="page-hero container"><span class="eyebrow">COMMUNITY CARE</span><h1>Admin overview.</h1><p>Moderate listings and monitor activity. Admin access is enforced on the server.</p></section><section class="container admin-layout"><div class="stats-grid"><?php foreach(['Registered users'=>'users','All listings'=>'listings','Available listings'=>'available','Swap requests'=>'requests','Completed swaps'=>'completed'] as $label=>$key): ?><div class="stat-card"><span><?= e(strtoupper($label)) ?></span><strong><?= (int)$stats[$key] ?></strong><small>Current total</small></div><?php endforeach; ?></div><div class="admin-panel" style="margin-top:25px"><h2 style="font-size:28px">User directory</h2><table class="admin-table"><thead><tr><th>USER</th><th>LOCATION</th><th>ROLE</th><th>JOINED</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?= e($u['name']) ?><br><small><?= e($u['email']) ?></small></td><td><?= e($u['location']) ?></td><td><?= e($u['role']) ?></td><td><?= e(date('M j, Y',strtotime($u['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="admin-panel" style="margin-top:25px"><h2 style="font-size:28px">Listing moderation</h2><table class="admin-table"><thead><tr><th>ITEM</th><th>OWNER</th><th>VALUE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($listings as $l): ?><tr><td><a href="listing.php?id=<?= (int)$l['id'] ?>"><?= e($l['title']) ?></a><br><small><?= e($l['category']) ?> · <?= e($l['location']) ?></small></td><td><?= e($l['owner_name']) ?></td><td>₹<?= number_format((float)$l['estimated_value'],0) ?></td><td><?= e($l['status']) ?></td><td><?php if($l['status']==='hidden'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="action" value="restore"><button type="submit">Restore</button></form><?php elseif($l['status']!=='swapped'): ?><form method="post" data-confirm="Hide this listing from the marketplace?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="listing_id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="action" value="hide"><button type="submit">Hide listing</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><div class="admin-panel" style="margin-top:25px"><h2 style="font-size:28px">Reported disputes</h2><?php if(!$disputes): ?><p class="value-note">No disputes have been reported.</p><?php else: ?><table class="admin-table"><thead><tr><th>SWAP</th><th>REPORTED BY</th><th>DETAILS</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($disputes as $d): ?><tr><td>#<?= (int)$d['swap_id'] ?></td><td><?= e($d['reporter']) ?></td><td><?= e($d['details']) ?></td><td><?= e($d['status']) ?></td><td><?php if($d['status']!=='resolved'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="resolve_dispute"><input type="hidden" name="dispute_id" value="<?= (int)$d['id'] ?>"><button type="submit">Mark resolved</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></section><?php require __DIR__.'/includes/footer.php'; ?>
